using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.SGR.Casas;namespace GraphApi.Services.SGR.Casas{    public class CasasService : ICasasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public CasasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadCasas>> GetCasas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM sgr.vsCasas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadCasas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetCasasDynamic(            int? casaID,            int? condominioID,            string? nombreCondominio,            string? direccionCondominio,            string? direccionCasa,            string? numeroExtCasa,            int? propietarioUsuarioID,            string? nombrePropietario,            string? correoPropietario,            string? fotoUrlPropietario,            string? telefonoPropietario,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "CasaID, CondominioID, NombreCondominio, DireccionCondominio, DireccionCasa, NumeroExtCasa, PropietarioUsuarioID, NombrePropietario, CorreoPropietario, FotoUrlPropietario, TelefonoPropietario, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM sgr.vsCasas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (casaID.HasValue)            {                vSql.Append(" AND CasaID = @CasaID");                vParameters.Add("CasaID",casaID);            }            if (!string.IsNullOrWhiteSpace(nombreCondominio))            {                vSql.Append(" AND NombreCondominio LIKE @NombreCondominio");                vParameters.Add("NombreCondominio",$"%{nombreCondominio}%");            }            if (!string.IsNullOrWhiteSpace(direccionCondominio))            {                vSql.Append(" AND DireccionCondominio LIKE @DireccionCondominio");                vParameters.Add("DireccionCondominio",$"%{direccionCondominio}%");            }            if (!string.IsNullOrWhiteSpace(direccionCasa))            {                vSql.Append(" AND DireccionCasa LIKE @DireccionCasa");                vParameters.Add("DireccionCasa",$"%{direccionCasa}%");            }            if (!string.IsNullOrWhiteSpace(numeroExtCasa))            {                vSql.Append(" AND NumeroExtCasa LIKE @NumeroExtCasa");                vParameters.Add("NumeroExtCasa",$"%{numeroExtCasa}%");            }            if (!string.IsNullOrWhiteSpace(nombrePropietario))            {                vSql.Append(" AND NombrePropietario LIKE @NombrePropietario");                vParameters.Add("NombrePropietario",$"%{nombrePropietario}%");            }            if (!string.IsNullOrWhiteSpace(correoPropietario))            {                vSql.Append(" AND CorreoPropietario LIKE @CorreoPropietario");                vParameters.Add("CorreoPropietario",$"%{correoPropietario}%");            }            if (!string.IsNullOrWhiteSpace(fotoUrlPropietario))            {                vSql.Append(" AND FotoUrlPropietario LIKE @FotoUrlPropietario");                vParameters.Add("FotoUrlPropietario",$"%{fotoUrlPropietario}%");            }            if (!string.IsNullOrWhiteSpace(telefonoPropietario))            {                vSql.Append(" AND TelefonoPropietario LIKE @TelefonoPropietario");                vParameters.Add("TelefonoPropietario",$"%{telefonoPropietario}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadCasas> CreateCasas(clCreateCasas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO sgr.Casas                (CondominioID, DireccionCasa, NumeroExtCasa, PropietarioUsuarioID, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@CondominioID, @DireccionCasa, @NumeroExtCasa, @PropietarioUsuarioID, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.CondominioID,                objInput.DireccionCasa,                objInput.NumeroExtCasa,                objInput.PropietarioUsuarioID,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT CasaID, CondominioID, NombreCondominio, DireccionCondominio, DireccionCasa, NumeroExtCasa, PropietarioUsuarioID, NombrePropietario, CorreoPropietario, FotoUrlPropietario, TelefonoPropietario, bEliminado                FROM sgr.vsCasas (NOLOCK)                WHERE CasaID = @CasaID;";            var vReadParams = new { CasaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadCasas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Casa con ID {vNewId}.");            return vCreated;        }        public async Task<clReadCasas?> UpdateCasas(clUpdateCasas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("CasaID", objInput.CasaID);            if (objInput.CondominioID != null)            {                vSets.Add("CondominioID = @CondominioID");                vParameters.Add("CondominioID", objInput.CondominioID);            }            if (objInput.DireccionCasa is not null)            {                vSets.Add("DireccionCasa = @DireccionCasa");                vParameters.Add("DireccionCasa", objInput.DireccionCasa);            }            if (objInput.NumeroExtCasa is not null)            {                vSets.Add("NumeroExtCasa = @NumeroExtCasa");                vParameters.Add("NumeroExtCasa", objInput.NumeroExtCasa);            }            if (objInput.PropietarioUsuarioID != null)            {                vSets.Add("PropietarioUsuarioID = @PropietarioUsuarioID");                vParameters.Add("PropietarioUsuarioID", objInput.PropietarioUsuarioID);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE sgr.Casas                SET {vSetClause}                WHERE CasaID = @CasaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT CasaID, CondominioID, NombreCondominio, DireccionCondominio, DireccionCasa, NumeroExtCasa, PropietarioUsuarioID, NombrePropietario, CorreoPropietario, FotoUrlPropietario, TelefonoPropietario, bEliminado                FROM sgr.vsCasas (NOLOCK)                WHERE CasaID = @CasaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadCasas>(sSelect, new {  objInput.CasaID });        }        public async Task<bool> DeleteCasas(int nCasasID)        {            const string sSql = @"                DELETE FROM sgr.Casas                WHERE CasaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nCasasID });            return vAffected > 0;        }    }}